function getMaintenanceSchedule(rv) {
	const isDiesel = rv.fuelType === "Diesel";
	const isTowable = rv.fuelType.includes("towable") || rv.fuelType.includes("truck camper");
	rv.type;
	const base = [
		{
			task: "Roof Seal Inspection & Re-caulk",
			interval: "Every 12 months",
			category: "Exterior",
			priority: "Critical"
		},
		{
			task: "Slideout Mechanism Lubrication",
			interval: "Every 3 months",
			category: "RV Systems",
			priority: "Important"
		},
		{
			task: "Slideout Rubber Seal Treatment",
			interval: "Every 3 months",
			category: "Exterior",
			priority: "Important"
		},
		{
			task: "Fresh/Gray/Black Tank Flush & Treatment",
			interval: "Every 3 months",
			category: "RV Systems",
			priority: "Important"
		},
		{
			task: "Water Heater Anode Rod Replacement",
			interval: "Every 12 months",
			category: "RV Systems",
			priority: "Important"
		},
		{
			task: "LP Gas Leak Test",
			interval: "Every 12 months",
			category: "Safety",
			priority: "Critical"
		},
		{
			task: "Smoke & CO Detector Battery Test",
			interval: "Every 6 months",
			category: "Safety",
			priority: "Critical"
		},
		{
			task: "Fire Extinguisher Inspection",
			interval: "Every 12 months",
			category: "Safety",
			priority: "Critical"
		},
		{
			task: "Awning Fabric Inspection & Lubrication",
			interval: "Every 12 months",
			category: "Exterior",
			priority: "Routine"
		},
		{
			task: "Battery Water Level Check (flooded)",
			interval: "Every 3 months",
			category: "RV Systems",
			priority: "Important"
		},
		{
			task: "Interior Appliance Inspection",
			interval: "Every 12 months",
			category: "Interior",
			priority: "Routine"
		},
		{
			task: "Winterization / Dewinterization",
			interval: "Seasonal",
			category: "RV Systems",
			priority: "Important"
		},
		{
			task: "Exterior Wash & Wax / Polish",
			interval: "Every 6 months",
			category: "Exterior",
			priority: "Routine"
		},
		{
			task: "Refrigerator Coil Cleaning",
			interval: "Every 12 months",
			category: "Interior",
			priority: "Routine"
		},
		{
			task: "Furnace Vent & Burner Cleaning",
			interval: "Every 12 months",
			category: "RV Systems",
			priority: "Important"
		},
		{
			task: "AC Filter Cleaning",
			interval: "Every 3 months",
			category: "Interior",
			priority: "Important"
		},
		{
			task: "Slide Topper Inspection",
			interval: "Every 12 months",
			category: "Exterior",
			priority: "Routine"
		},
		{
			task: "Sewer Hose & Fitting Inspection",
			interval: "Every 12 months",
			category: "RV Systems",
			priority: "Important"
		}
	];
	if (!isTowable) {
		if (isDiesel) base.unshift({
			task: "Engine Oil & Filter Change",
			interval: "Every 15,000 miles",
			category: "Engine",
			priority: "Critical"
		}, {
			task: "Diesel Fuel Filter Replacement",
			interval: "Every 30,000 miles",
			category: "Engine",
			priority: "Critical"
		}, {
			task: "DEF (AdBlue) Level Check",
			interval: "Every 5,000 miles",
			category: "Engine",
			priority: "Important"
		}, {
			task: "Air Filter Inspection",
			interval: "Every 30,000 miles",
			category: "Engine",
			priority: "Important"
		}, {
			task: "Coolant Flush",
			interval: "Every 100,000 miles or 5 years",
			category: "Engine",
			priority: "Important"
		}, {
			task: "Transmission Service",
			interval: "Every 50,000 miles",
			category: "Chassis",
			priority: "Critical"
		}, {
			task: "Turbocharger Inspection",
			interval: "Every 50,000 miles",
			category: "Engine",
			priority: "Important"
		}, {
			task: "Serpentine Belt Inspection",
			interval: "Every 50,000 miles",
			category: "Engine",
			priority: "Critical"
		}, {
			task: "Diesel Exhaust Fluid (DEF) System Inspection",
			interval: "Every 30,000 miles",
			category: "Engine",
			priority: "Important"
		});
		else base.unshift({
			task: "Engine Oil & Filter Change",
			interval: "Every 5,000 miles",
			category: "Engine",
			priority: "Critical"
		}, {
			task: "Air Filter Replacement",
			interval: "Every 30,000 miles",
			category: "Engine",
			priority: "Important"
		}, {
			task: "Spark Plug Replacement",
			interval: "Every 60,000 miles",
			category: "Engine",
			priority: "Important"
		}, {
			task: "Coolant Flush",
			interval: "Every 50,000 miles or 5 years",
			category: "Engine",
			priority: "Important"
		}, {
			task: "Transmission Service",
			interval: "Every 30,000 miles",
			category: "Chassis",
			priority: "Critical"
		}, {
			task: "Serpentine Belt Replacement",
			interval: "Every 60,000 miles",
			category: "Engine",
			priority: "Critical"
		}, {
			task: "Throttle Body Cleaning",
			interval: "Every 30,000 miles",
			category: "Engine",
			priority: "Routine"
		});
		base.push({
			task: "Chassis Lubrication",
			interval: "Every 12 months or 15,000 miles",
			category: "Chassis",
			priority: "Important"
		}, {
			task: "Brake Inspection",
			interval: "Every 12 months",
			category: "Chassis",
			priority: "Critical"
		}, {
			task: "Brake Fluid Flush",
			interval: "Every 2 years",
			category: "Chassis",
			priority: "Important"
		}, {
			task: "Tire Rotation & Pressure Check",
			interval: "Every 7,500 miles",
			category: "Chassis",
			priority: "Critical"
		}, {
			task: "Tire Age Inspection (replace at 7 years)",
			interval: "Annually",
			category: "Chassis",
			priority: "Critical"
		}, {
			task: "Generator Oil Change",
			interval: "Every 100-150 hours",
			category: "RV Systems",
			priority: "Critical"
		}, {
			task: "Generator Load Test",
			interval: "Every 12 months",
			category: "RV Systems",
			priority: "Important"
		}, {
			task: "Generator Air Filter Replacement",
			interval: "Every 200 hours",
			category: "RV Systems",
			priority: "Important"
		}, {
			task: "Leveling System Hydraulic Fluid",
			interval: "Every 24 months",
			category: "Chassis",
			priority: "Important"
		}, {
			task: "Air Suspension Inspection (diesel)",
			interval: "Every 12 months",
			category: "Chassis",
			priority: "Important"
		}, {
			task: "Steering System Inspection",
			interval: "Every 12 months",
			category: "Chassis",
			priority: "Critical"
		}, {
			task: "Differential Service",
			interval: "Every 50,000 miles",
			category: "Chassis",
			priority: "Important"
		});
	} else base.push({
		task: "Tire Pressure Check & Rotation",
		interval: "Every 7,500 miles towed",
		category: "Chassis",
		priority: "Critical"
	}, {
		task: "Tire Age Inspection (replace at 7 years)",
		interval: "Annually",
		category: "Chassis",
		priority: "Critical"
	}, {
		task: "Wheel Bearing Inspection & Repack",
		interval: "Every 12,000 miles",
		category: "Chassis",
		priority: "Critical"
	}, {
		task: "Brake Controller Calibration",
		interval: "Every 12 months",
		category: "Safety",
		priority: "Important"
	}, {
		task: "Electric Brake Magnet Inspection",
		interval: "Every 12,000 miles",
		category: "Chassis",
		priority: "Critical"
	}, {
		task: "Hitch Ball & Coupler Inspection",
		interval: "Before every trip",
		category: "Safety",
		priority: "Critical"
	}, {
		task: "Safety Chain & Breakaway Cable",
		interval: "Before every trip",
		category: "Safety",
		priority: "Critical"
	}, {
		task: "Landing Gear Lubrication",
		interval: "Every 6 months",
		category: "Chassis",
		priority: "Important"
	}, {
		task: "Equalizer Hitch Inspection",
		interval: "Every 12 months",
		category: "Safety",
		priority: "Important"
	});
	return base;
}
